```ts
export const extractMessage = (str: string) => {
  const regex = /-- sources:start --(.*)-- sources:end --/s;
  const match = regex.exec(str);
  const sourceStr = match?.[1];

  const sources: { name: string; url: string }[] = JSON.parse(
    sourceStr?.trim() || "[]",
  );

  const answer = str
    .replace(regex, "")
    .trim();

  return { sources, answer };
};
```

