Hey! I'm interested in this feature as well, but for now, I've come up with a workaround to make it work, which is fully compatible with experimental `useObject`. Thought I could share it, so maybe it can be useful for someone for now.

```ts
// route.ts

import { streamObject } from "ai";
import { z } from "zod";

// Define your schema for the streamed object
const exampleSchema = z.object({
  name: z.string(),
  description: z.string(),
  tags: z.array(z.string())
});

export async function POST(req: Request) {
  const { prompt } = await req.json();

  // Create the streamObject
  const result = streamObject({
    model: yourModel, // your AI model here
    schema: exampleSchema,
    system: "Generate a creative character based on the prompt",
    prompt,
  });

  const { textStream } = result;

  // Add custom wrapper data around the streamed object
  const prefix = '{"data":';
  const suffix = ',"status":"success","timestamp":"' + new Date().toISOString() + '","requestId":"' + crypto.randomUUID() + '"}';

  // Create custom stream that wraps the original with additional data
  const customStream = new ReadableStream({
    async start(controller) {
      // Send opening wrapper
      controller.enqueue(new TextEncoder().encode(prefix));

      // Stream the actual object content
      for await (const chunk of textStream) {
        controller.enqueue(new TextEncoder().encode(chunk));
      }

      // You can add some custom action here and append some data like item ID from DB

      // Send closing wrapper with custom data
      controller.enqueue(new TextEncoder().encode(suffix));
      controller.close();
    },
  });

  return new Response(customStream, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
    },
  });
}
```

Just remember that you need to use different schema on client side now, as data shape is different.

