                    parts: candidate.content.parts.filter(
                      (part) =>
                        !part.executableCode && !part.codeExecutionResult,
                    ),
                  },
                };
              }
              return candidate;
            });
          }

          return new Response(JSON.stringify(resBody), {
            status: res.status,
            statusText: res.statusText,
            headers: res.headers,
          });
        });
      },
    })('gemini-2.0-flash-thinking-exp-01-21');
