```typescript
import { SWRConfig } from 'swr';

// ... existing imports ...

function ChatInner({ id, initialMessages, session }: {
  id: string;
  initialMessages: Message[];
  session: Session | null;
}) {
  // ... existing Chat component code ...
}

export function Chat(props: {
  id: string;
  initialMessages: Message[];
  session: Session | null;
}) {
  return (
    <SWRConfig 
      value={{
        fetcher: undefined, // Disable global fetcher for this component
      }}
    >
      <ChatInner {...props} />
    </SWRConfig>
  );
}
```

