        buffer = '';
      }
      else if (buffer.includes('{type:middle}')) {
        data.appendMessageAnnotation({
          type: 'middle',
          text: buffer,
        });
        buffer = '';
      }
      else if (buffer.includes('{type:end}')) {
        data.appendMessageAnnotation({
          type: 'end',
          text: buffer,
        });
        buffer = '';
      }
    },
    onFinish() {
      data.close();
    },
  });
