``` 
export default function Chat({
  chatId,
  agentId,
  initialMessages,
  projectId,
}: {
  chatId: string;
  agentId?: string;
  initialMessages: UIMessage[];
  projectId?: string;
}) {
  const queryClient = useQueryClient();
  const { messages, status, sendMessage, error, stop } = useChat({
    transport: new DefaultChatTransport({
      api: '/api/chat/streaming',
      credentials: 'include',
      headers: { 'Custom-Header': 'value' },
    }),
    messages: initialMessages,
  });

  const [input, setInput] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (status === 'streaming') {
      setIsSubmitting(true);
    } else {
      setIsSubmitting(false);
    }
  }, [status]);

  const [isLoading, setIsLoading] = useState({
    isFetchingMessages: false,
    isSubmitting: isSubmitting,
  });

  const handleSubmit = () => {
    sendMessage(
      {
        text: input,
      },
      {
        body: {
          chatId,
          agentId,
          projectId,
        },
      }
    );
  };

  useEffect(() => {
    setIsLoading(prev => ({
      ...prev,
      isSubmitting: isSubmitting,
    }));
  }, [isSubmitting]);

  if (isLoading.isFetchingMessages) {
    return <LoadingState />;
  }

  return (
    <div>
      {messages.length === 0 && initialMessages.length === 0 && !projectId && (
        <EmptyChatInput
          isLoading={isLoading.isSubmitting}
          input={input}
          setInput={setInput}
          onSubmit={handleSubmit}
          status={status}
          chatId={chatId}
        />
      )}

      {messages.length === 0 && initialMessages.length === 0 && projectId && (
        <ProjectPage
          agentId={agentId || ''}
          input={input}
          setInput={setInput}
          onSubmit={handleSubmit}
          chatId={chatId}
          projectId={projectId}
        />
      )}

      {messages.length > 0 && (
        <ChatUI
          messages={messages}
          isLoading={isLoading.isSubmitting}
          input={input}
          setInput={setInput}
          handleSubmit={handleSubmit}
          status={status}
          chatId={chatId}
          projectId={projectId}
        />
      )}
    </div>
  );
}

