I use middleware as a (temporary) work around

```
import type { LanguageModelV1Middleware, LanguageModelV1StreamPart } from 'ai';
import { customAlphabet } from 'nanoid';

const lowercase = 'abcdefghijklmnopqrstuvwxyz';
const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const numbers = '0123456789';

const alphanumeric = numbers + lowercase + uppercase;

// Similar to the id that is generated by OpenAI.
const nanoOpenAI = customAlphabet(alphanumeric, 24);

export const toolIdMiddleware: LanguageModelV1Middleware = {
  wrapGenerate: async ({ doGenerate }) => {
    // We do not use generate, so no tool call id workaround.
    const result = await doGenerate();
    return result;
  },

  wrapStream: async ({ doStream }) => {
    const { stream, ...rest } = await doStream();

    const transformStream = new TransformStream<LanguageModelV1StreamPart, LanguageModelV1StreamPart>({
      transform(chunk, controller) {
        if (chunk.type === 'tool-call') {
          const newId = nanoOpenAI();
          chunk.toolCallId = 'call_' + newId;
        }

        controller.enqueue(chunk);
      },
    });

    return {
      stream: stream.pipeThrough(transformStream),
      ...rest,
    };
  },
};

