This is my implementation but I haven't tested it:

```ts
const urlsInResultSchema = z.object({
  urls: z.array(z.string()),
});

export function urlToFileParts(): LanguageModelV1Middleware {
  return {
    transformParams: async ({ params }): Promise<LanguageModelV1CallOptions> => {
      const prompt = params.prompt;
      const newPrompt: LanguageModelV1Prompt = [];
      for (const message of prompt) {
        newPrompt.push(message);
        if (message.role === "tool") {
          const parts: (FilePart | TextPart)[] = [];
          for (const resultPart of message.content) {
            // Each resultPart.result is the JSON returned by tool
            const result = resultPart.result;
            const parsed = urlsInResultSchema.safeParse(result);
            if (parsed.success) {
              for (const url of parsed.data.urls) {
                parts.push({
                  type: "file" as const,
                  data: url,
                  mimeType: "image/jpeg",
                });
              }
            }
          }
          if (parts.length > 0) {
            newPrompt.push({
              role: "assistant",
              content: parts,
            } as any);
          }
        }
      }

      return {
        ...params,
        prompt: newPrompt,
      };
    },
  };
}
