// SiliconFlow fetch need special processing, because its streaming response format is different from OpenAI, so it cannot call tools
const customFetch: typeof fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
  // console.log('customFetch: ', input, init);
  const response = await fetch(input, init);

  // If this is a streaming response
  if (response.headers.get('content-type')?.includes('text/event-stream')) {
    const reader = response.body?.getReader();
    const decoder = new TextDecoder();

    return new Response(
      new ReadableStream({
        async start(controller) {
          try {
            while (true) {
              const { done, value } = await reader!.read();
              if (done) {
                controller.close();
                break;
              }

              let chunk = decoder.decode(value);
              // Fix the tool call format
              chunk = chunk.replace(/"type":\s*""/g, '"type":"function"');
              chunk = chunk.replace(/"type":\s*null/g, '"type":"function"');
              controller.enqueue(new TextEncoder().encode(chunk));
            }
          } catch (e: unknown) {
            controller.error(e);
          }
        },
      }),
      response
    );
  }

  return response;
};

