now my fix (work for me):

``` ts
/** biome-ignore-all lint/suspicious/noExplicitAny: <allow any in this file> */
import { delay as originalDelay, type Tool } from "@ai-sdk/provider-utils";
import type { TextStreamPart } from "ai";
import { InvalidArgumentError } from "ai";

const CHUNKING_REGEXPS = {
  word: /\S+\s+/m,
  line: /\n+/m,
};

/**
 * Detects the first chunk in a buffer.
 *
 * @param buffer - The buffer to detect the first chunk in.
 *
 * @returns The first detected chunk, or `undefined` if no chunk was detected.
 */
export type ChunkDetector = (buffer: string) => string | undefined | null;

/**
 * Smooths text streaming output.
 *
 * @param delayInMs - The delay in milliseconds between each chunk. Defaults to 10ms. Can be set to `null` to skip the delay.
 * @param chunking - Controls how the text is chunked for streaming. Use "word" to stream word by word (default), "line" to stream line by line, or provide a custom RegExp pattern for custom chunking.
 *
 * @returns A transform stream that smooths text streaming output.
 */
export function smoothStream<TOOLS extends ToolSet>({
  delayInMs = 10,
  chunking = "word",
  _internal: { delay = originalDelay } = {},
}: {
  delayInMs?: number | null;
  chunking?: "word" | "line" | RegExp | ChunkDetector;
  /**
   * Internal. For test use only. May change without notice.
   */
  _internal?: {
    delay?: (delayInMs: number | null) => Promise<void>;
  };
} = {}): (options: {
  tools: TOOLS;
}) => TransformStream<TextStreamPart<TOOLS>, TextStreamPart<TOOLS>> {
  let detectChunk: ChunkDetector;

  if (typeof chunking === "function") {
    detectChunk = (buffer) => {
      const match = chunking(buffer);

      if (match == null) {
        return null;
      }

      if (!match.length) {
        throw new Error(`Chunking function must return a non-empty string.`);
      }

      if (!buffer.startsWith(match)) {
        throw new Error(
          `Chunking function must return a match that is a prefix of the buffer. Received: "${match}" expected to start with "${buffer}"`,
        );
      }

      return match;
    };
  } else {
    const chunkingRegex =
      typeof chunking === "string" ? CHUNKING_REGEXPS[chunking] : chunking;

    if (chunkingRegex == null) {
      // FIX TYPE ERROR HERE
      throw new InvalidArgumentError({
        parameter: "chunking",
        value: chunking,
        message: `Chunking must be "word" or "line" or a RegExp. Received: ${chunking}`,
      });
    }

    detectChunk = (buffer) => {
      const match = chunkingRegex.exec(buffer);

      if (!match) {
        return null;
      }

      return buffer.slice(0, match.index) + match?.[0];
    };
  }

  return () => {
    let buffer = "";
    let id = "";

    return new TransformStream<TextStreamPart<TOOLS>, TextStreamPart<TOOLS>>({
      async transform(chunk, controller) {
        // FIX MISSING "reasoning-delta" CHUNK HERE
        if (chunk.type !== "text-delta" && chunk.type !== "reasoning-delta") {
          if (buffer.length > 0) {
            controller.enqueue({ type: "text-delta", text: buffer, id });
            buffer = "";
          }

          controller.enqueue(chunk);
          return;
        }

        if (chunk.id !== id && buffer.length > 0) {
          controller.enqueue({ type: "text-delta", text: buffer, id });
          buffer = "";
        }

        buffer += chunk.text;
        id = chunk.id;

        // FIX LINT ERROR HERE
        let match: string | undefined | null = detectChunk(buffer);

        while (match != null) {
          // FIX CHUNK TYPE HERE
          controller.enqueue({ type: chunk.type, text: match, id });
          buffer = buffer.slice(match.length);

          await delay(delayInMs);
          match = detectChunk(buffer);
        }
      },
    });
  };
}

type ToolSet = Record<
  string,
  (Tool<never, never> | Tool<any, any> | Tool<any, never> | Tool<never, any>) &
    Pick<
      Tool<any, any>,
      | "execute"
      | "onInputAvailable"
      | "onInputStart"
      | "onInputDelta"
      | "needsApproval"
    >
>;

```

