Hello, as of the `5.0.0-alpha.13` there is now an option `includeRawChunks: true` in `streamText()` function

using this with the custom middleware i was able to extract reasoning

Here is the example
```ts
import type { LanguageModelV2Middleware, LanguageModelV2StreamPart } from "@ai-sdk/provider";

export const extractReasoningMiddleware: LanguageModelV2Middleware = {
  wrapStream: async ({ doStream, params }) => {
    const { stream, ...rest } = await doStream();

    const transformStream = new TransformStream<LanguageModelV2StreamPart, LanguageModelV2StreamPart>({
      transform(chunk, controller) {
        if (chunk.type === "raw") {
          const reasoning = chunk.rawValue.choices[0].delta.reasoning;
          if (reasoning) {
            controller.enqueue({
              type: "reasoning",
              text: reasoning,
              providerMetadata: {},
            });
          }
        }

        controller.enqueue(chunk);
      },
    });

    return {
      stream: stream.pipeThrough(transformStream),
      ...rest,
    };
  },
};
```

```ts
const stream = streamText({
  model: wrapLanguageModel({
    model: yourModel,
    middleware: extractReasoningMiddleware,
  }),
  includeRawChunks: true,
  // rest of the params
});
```

