            execute: async ({ goal }) => {
              const result2 = streamText({
                // different system prompt, different model, no tools:
                model: openai('gpt-4o'),
                system:
                  'You are a helpful assistant with a different system prompt. Repeat the extract user goal in your answer.',
                // continue the workflow stream with the messages from the previous step:
                messages: [
                  ...convertToCoreMessages(messages),
                ],
              });

              // forward the 2nd result to the client (incl. the finish event):
              result2.mergeIntoDataStream(dataStream, {
                experimental_sendStart: false, // omit the start event
              });
              return await result2.text;
            }, 
          }),
        },
      });

      // forward the initial result to the client without the finish event:
      result1.mergeIntoDataStream(dataStream, {
        experimental_sendFinish: false, // omit the finish event
      });

      // note: you can use any programming construct here, e.g. if-else, loops, etc.
      // workflow programming is normal programming with this approach.

      // example: continue stream with forced tool call from previous step
    },
  });
}
```

However, be aware that this feature hasn't been designed for nested calls like this.

For anyone else running into this. Here's a non-invasive fix to add ping support to the client, by wrapping the original transport. 

PingAwareTransportWrapper:
```
import type { JSONRPCMessage, JSONRPCResponse, MCPTransport } from "ai";

export class PingAwareTransportWrapper implements MCPTransport {
  private originalTransport: MCPTransport;

  onmessage?: (message: JSONRPCMessage | JSONRPCResponse) => void;
  onclose?: () => void;
  onerror?: (error: Error) => void;

  constructor(originalTransport: MCPTransport) {
    this.originalTransport = originalTransport;

    // Proxy the original transport's handlers
    this.originalTransport.onclose = () => this.onclose?.();
    this.originalTransport.onerror = (error) => this.onerror?.(error);
    this.originalTransport.onmessage = (message) => {
      // Handle ping messages first
      if ("method" in message && message.method === "ping") {
        this.handlePing(message);
        return;
      }

      // Pass all other messages to MCPClient's handler
      this.onmessage?.(message);
    };
  }

  private handlePing(message: JSONRPCMessage): void {
    if ("id" in message) {
      const response: JSONRPCResponse = {
        jsonrpc: "2.0",
        id: message.id,
        result: {},
      };
      this.originalTransport.send(response).catch((error) => {
        this.onerror?.(error);
      });
    }
    // If no ID is present (notification ping), we don't need to respond
  }

  async start(): Promise<void> {
    return this.originalTransport.start();
  }

  async send(message: JSONRPCMessage | JSONRPCResponse): Promise<void> {
    return this.originalTransport.send(message);
  }

  async close(): Promise<void> {
    return this.originalTransport.close();
  }
}
```

