If you want to retain some compat between nullables and optionals maybe this could help: 

```ts
export function makeNullablePropsOptional<Schema extends z.ZodObject<any>>(schema: Schema): Schema {
  const entries = Object.entries(schema.shape) as [keyof Schema['shape'], z.ZodTypeAny][]
  const newProps = entries.reduce<any>((acc, [key, value]) => {
    if (value instanceof z.ZodNullable) {
      acc[key] = z.optional(value.unwrap())
    } else if (value instanceof z.ZodOptional && value.unwrap() instanceof z.ZodObject) {
      // Handle optional nested objects by recursively transforming them
      acc[key] = z.optional(makeNullablePropsOptional(value.unwrap() as z.ZodObject<any>))
    } else if (value instanceof z.ZodObject) {
      // Handle required nested objects
      acc[key] = makeNullablePropsOptional(value as z.ZodObject<any>)
    } else {
      acc[key] = value
    }
    return acc
  }, {})

  return z.object(newProps) as Schema
}

export function zodOptionalsToNullables<Schema extends z.ZodObject<any>>(schema: Schema): Schema {
  const entries = Object.entries(schema.shape) as [keyof Schema['shape'], z.ZodTypeAny][]
  const newProps = entries.reduce<any>((acc, [key, value]) => {
    if (value instanceof z.ZodOptional) {
      acc[key] = z.nullable(value.unwrap())
    } else if (value instanceof z.ZodNullable && value.unwrap() instanceof z.ZodObject) {
      // Handle nullable nested objects by recursively transforming them
      acc[key] = z.nullable(zodOptionalsToNullables(value.unwrap() as z.ZodObject<any>))
    } else if (value instanceof z.ZodObject) {
      // Handle required nested objects
      acc[key] = zodOptionalsToNullables(value as z.ZodObject<any>)
    } else {
      acc[key] = value
    }
    return acc
  }, {})

  return z.object(newProps) as Schema
}

