Hi just wanted to share a workaround that we used on (CodeWords)[codewords.ai]

So instead of relying on the AbortSignal from the request we create an AbortSignal ourselves that is linked to Redis PubSub

```typescript
  const getAbortChannelName = (chatId: string) => `chat:abort:${chatId}`;

  const ABORT_MESSAGE = "ABORT";

  const abortController = new AbortController();

  const getAbortSignal = (): AbortSignal => {
    const channel = getAbortChannelName(chatId);

    const listener = async (message: string) => {
      if (message === ABORT_MESSAGE) {
        abortController.abort();
        await sub.unsubscribe(channel, listener);
      }
    };
    void sub.subscribe(channel, listener);

    return abortController.signal;
  };

```

we then pass this to streamText

```typescript
    const result = streamText({
      abortSignal: getAbortSignal(),
       ...
```

Then we have an endpoint that is called by the FE that publishes a message to the redis channel

```typescript
  const sendAbortMessage = async () => {
    await pub.publish(getAbortChannelName(chatId), ABORT_MESSAGE);
  };
```

