```ts
import {
  SpanProcessor,
  ReadableSpan,
  SpanExporter
} from '@opentelemetry/sdk-trace-base'

export class SanitizingSpanProcessor implements SpanProcessor {
  private _exporter: SpanExporter

  constructor(exporter: SpanExporter) {
    this._exporter = exporter
  }

  onStart(span: ReadableSpan): void {}

  onEnd(span: ReadableSpan): void {
    // Sanitize attributes
    for (const [key, value] of Object.entries(span.attributes)) {
      if (
        value === null ||
        Number.isNaN(value) ||
        (typeof value !== 'string' &&
          typeof value !== 'number' &&
          typeof value !== 'boolean')
      ) {
        // You can either delete or stringify, here we stringify
        span.attributes[key] = JSON.stringify(value)
      }
    }
    console.log('>>span', span)
    this._exporter.export([span], () => {})
  }

  async shutdown(): Promise<void> {
    await this._exporter.shutdown()
  }

  async forceFlush(): Promise<void> {
    await this._exporter.forceFlush?.()
  }
}

const sdk = new NodeSDK({
  resource,
  spanProcessors: [
    new SanitizingSpanProcessor(
      new OTLPTraceExporter({
        url: 'http://localhost:4318/v1/traces'
      })
    )
  ]
})
```

