<summary>parseMessageParts.ts</summary>

```ts
type UIMessagePartType = "text" | "thinking";

interface ParseUIMessagePartsProps {
  content: string;
  /**
   * @default "thinking"
   */
  tag?: string;
}

/**
 * Given a string LLM response containing partial or whole <thinking> tags,
 * parse text into `UIMessagePartType`s and return in array with parts
 * segmented by "thinking" or "text".
 *
 * Note, AI SDK has native [extractReasoningMiddleware](https://ai-sdk.dev/docs/reference/ai-sdk-core/extract-reasoning-middleware)
 * but this doesn't work for LLM's that don't support reasoning like Amazon Nova.
 * You could edit system prompt to remove thinking but that would reduce LLM
 * accuracy so this solution just removes `<thinking>` tags from response and
 * parses them into `UIMessagePartType`s.
 *
 * Will also combine back-to-back thinking tags.
 *
 * @example
 * parseChatContent("<thinking>I'm thinking...</thinking>The answer is ...")
 * // [{ content: "I'm thinking...", type: "thinking" }, { content: "The answer is...", type: "text" }]
 */
export function parseUIMessageParts(
  props: ParseUIMessagePartsProps,
): { content: string; type: UIMessagePartType }[] {
  const { content, tag = "thinking" } = props;

  if (!content) return [];

  const openingTag = `<${tag}>`;
  const openingTagFirstChar = openingTag[0];
  const closingTag = `</${tag}>`;
  const closingTagFirstChar = closingTag[0];
  const results: { content: string; type: UIMessagePartType }[] = [];

  let textBuffer = "";
  let thinkingBuffer = "";
  let openingTagBuffer = "";
  let closingTagBuffer = "";
  let isThinking = false;

  function pushThinkingMessage(buffer: string) {
    // combine back-to-back thinking tags in 1 message part
    const lastMessagePart = results.at(-1);
    if (lastMessagePart?.type === "thinking") {
      lastMessagePart.content += `\n${buffer}`;
    } else {
      results.push({ content: buffer, type: "thinking" });
    }
  }

  for (const char of content) {
    if ((!isThinking && char === openingTagFirstChar) || openingTagBuffer) {
      if (textBuffer) {
        // if existing buffer, flush to results
        results.push({ content: textBuffer, type: "text" });
        textBuffer = "";
      }
      openingTagBuffer += char;
      if (openingTag.startsWith(openingTagBuffer)) {
        if (openingTagBuffer === openingTag) {
          isThinking = true;
          openingTagBuffer = "";
        }
      } else {
        // tag isn't a thinking tag so add chars back to buffer so it's used as text
        textBuffer += openingTagBuffer;
        openingTagBuffer = "";
      }
    } else if (isThinking) {
      if (char === closingTagFirstChar || closingTagBuffer) {
        closingTagBuffer += char;
        if (closingTag.startsWith(closingTagBuffer)) {
          if (closingTagBuffer === closingTag) {
            pushThinkingMessage(thinkingBuffer);
            isThinking = false;
            closingTagBuffer = "";
            thinkingBuffer = "";
          }
        } else {
          // tag isn't a closing tag so add chars back to buffer so it's used as text
          textBuffer += closingTagBuffer;
          closingTagBuffer = "";
        }
      } else {
        thinkingBuffer += char;
      }
    } else {
      textBuffer += char;
    }
  }

  if (textBuffer) {
    results.push({ content: textBuffer, type: "text" });
  }
  if (thinkingBuffer) {
    pushThinkingMessage(thinkingBuffer);
  }

  return results;
}

```

