import { useChat } from '@ai-sdk/react'
import { JSONValue, ToolInvocation, ToolResultPart } from 'ai';
import React from 'react'

function toToolCall(value: JSONValue): ToolInvocation | null {
    if (typeof value === 'object' && !Array.isArray(value)
        && typeof value?.state === 'string' && ['state', 'result'].includes(value?.state)) {
        return value as unknown as ToolInvocation
    }

    return null;
}
function processToolCallsFromAnnotations(rawAnnotations?: JSONValue[]): ToolInvocation[] {
    if (!rawAnnotations) return [] as ToolInvocation[];

    const lastState = {} as { [toolCallId: string]: ToolInvocation };
    const annotations = rawAnnotations.map(toToolCall).filter((v: ToolInvocation | null) => v != null);
    for (const part of annotations) {
        lastState[part.toolCallId] = part;
    }

    const result = [] as ToolInvocation[];
    const seen = new Set();
    for (const part of annotations) {
        if (!seen.has(part.toolCallId)) {
            seen.add(part.toolCallId);
            result.push(lastState[part.toolCallId]);
        }
    }
    return result;
}
