It is possible to do something like this:

```typescript
export function useChat<UI_MESSAGE extends UIMessage = UIMessage>(
    {
        experimental_throttle: throttleWaitMs,
        resume = false,
        ...options
    }: UseChatOptions<UI_MESSAGE> = {},
    deps: any[],
): UseChatHelpers<UI_MESSAGE> {
    const chat = useMemo(() => {
        return 'chat' in options ? options.chat : new Chat(options)
    }, [...deps])

    const subscribeToMessages = useCallback(
        (update: () => void) => chat['~registerMessagesCallback'](update, throttleWaitMs),
        [throttleWaitMs, chat],
    )

    const messages = useSyncExternalStore(
        subscribeToMessages,
        () => chat.messages,
        () => chat.messages,
    )
    const subscribeToStatus = useCallback(
        (cb: () => void) => chat['~registerStatusCallback'](cb),
        [chat],
    )

    const status = useSyncExternalStore(
        subscribeToStatus,
        () => chat.status,
        () => chat.status,
    )
    const subscribeToError = useCallback(
        (cb: () => void) => chat['~registerErrorCallback'](cb),
        [chat],
    )

    const error = useSyncExternalStore(
        subscribeToError,
        () => chat.error,
        () => chat.error,
    )

    const setMessages = useCallback(
        (messagesParam: UI_MESSAGE[] | ((messages: UI_MESSAGE[]) => UI_MESSAGE[])) => {
            if (typeof messagesParam === 'function') {
                messagesParam = messagesParam(messages)
            }

            chat.messages = messagesParam
        },
        [chat, messages],
    )

    useEffect(() => {
        if (resume) {
            chat.resumeStream()
        }
    }, [chat, resume])

    return {
        id: chat.id,
        messages,
        setMessages,
        sendMessage: chat.sendMessage,
        regenerate: chat.regenerate,
        stop: chat.stop,
        error,
        resumeStream: chat.resumeStream,
        status,
        addToolResult: chat.addToolResult,
    }
}
```
