			},
		});
	}

	async call(
		url: string,
		service: string,
		method: string,
		args: any[]
	): Promise<any> {
		const client = this.createClient(url);

		try {
			const response = await client.request('call', {
				service,
				method,
				args,
			});

			if (response.error) {
				throw new Error(
					`Odoo Error ${response.error.code}: ${response.error.message}`
