/**
 * Build an Odoo domain from a search criteria object
 */
function buildDomain(
	criteria: Record<string, any>,
	operator: 'and' | 'or' | 'not'
): any[] {
	const domainClauses: any[] = [];

	// Log the criteria for debugging
	console.log(
		'Building domain from criteria:',
		JSON.stringify(criteria)
	);

	// First, preprocess the criteria to normalize it
	const normalizedCriteria: Record<string, any> = {};

	for (const [field, value] of Object.entries(criteria)) {
		// Skip undefined/null values
		if (value === undefined || value === null) continue;

		// Handle arrays (especially for relational fields in [id, name] format)
		if (Array.isArray(value) && value.length >= 1) {
			// This is likely an Odoo many2one field representation [id, name]
			console.log(`Array value for field ${field}:`, value);
			// Use the ID (first element) for the search
			normalizedCriteria[field] = value[0];
			continue;
		}

		// If value is an object but not an array, we need to extract the actual value
		if (typeof value === 'object' && !Array.isArray(value)) {
			console.log(`Complex value for field ${field}:`, value);
			normalizedCriteria[field] = Object.values(value)[0];
		} else {
			// Use the value as is
			normalizedCriteria[field] = value;
		}
	}

	console.log(
		'Normalized criteria:',
		JSON.stringify(normalizedCriteria)
	);

	// Build the domain with the normalized criteria
	for (const [field, value] of Object.entries(normalizedCriteria)) {
		if (value === undefined || value === null) continue;

		const stringValue = String(value).trim();

		// Handle special patterns
		if (stringValue === '%') {
			// Has value
			domainClauses.push([field, '!=', false]);
		} else if (stringValue === '') {
			// No value
			domainClauses.push([field, '=', false]);
		} else if (
			typeof value === 'string' &&
			(value.startsWith('>') || value.startsWith('<'))
		) {
			// Comparison operator
			const op = value.charAt(0);
			const isEqual = value.charAt(1) === '=';
			const val = value.substring(isEqual ? 2 : 1);
			domainClauses.push([
				field,
				op + (isEqual ? '=' : ''),
				isNaN(Number(val)) ? val : Number(val),
			]);
		} else if (field === 'id' || field.endsWith('_id')) {
			// ID field
			domainClauses.push([field, '=', Number(value)]);
		} else if (typeof value === 'boolean') {
			// Boolean
			domainClauses.push([field, '=', value]);
		} else if (!isNaN(Number(value)) && typeof value !== 'string') {
			// Numeric
			domainClauses.push([field, '=', Number(value)]);
		} else {
			// Default: text search
			domainClauses.push([field, 'ilike', value]);
		}
	}

	// Apply operator
	if (domainClauses.length <= 1) {
		return domainClauses;
	}

	if (operator === 'or') {
		// OR requires prefix notation
		const domain = [];
		for (let i = 0; i < domainClauses.length - 1; i++) {
			domain.push('|');
		}
		domain.push(...domainClauses);
		return domain;
	} else if (operator === 'not') {
		// NOT for the entire set of conditions
		return [['!', domainClauses]];
	} else {
		// Default is AND (implicit in Odoo)
		return domainClauses;
	}
}
