I vibe-coded a 'modelMessagesToUiMessage' that might help someone temporarily. Have barely looked at the code, but seems to hold up for our use case at least.

```
export function modelMessagesToUiMessage(
  modelMessages: ResponseMessage[],
  assistantChatMessageId: string,
): UIMessage {
  const uiMessage: UIMessage = {
    id: assistantChatMessageId,
    role: 'assistant',
    parts: [],
  }

  for (const modelMessage of modelMessages) {
    switch (modelMessage.role) {
      case 'assistant': {
        if (Array.isArray(modelMessage.content)) {
          for (const content of modelMessage.content) {
            switch (content.type) {
              case 'text':
                uiMessage.parts.push({
                  type: 'text',
                  text: content.text,
                  ...(content.providerOptions
                    ? { providerMetadata: content.providerOptions }
                    : {}),
                })
                break
              case 'reasoning':
                uiMessage.parts.push({
                  type: 'reasoning',
                  text: content.text,
                  providerMetadata: content.providerOptions,
                })
                break
              case 'file':
                uiMessage.parts.push({
                  type: 'file',
                  mediaType: content.mediaType,
                  filename: content.filename,
                  url:
                    typeof content.data === 'string'
                      ? content.data
                      : content.data.toString(),
                  ...(content.providerOptions
                    ? { providerMetadata: content.providerOptions }
                    : {}),
                })
                break
              case 'tool-call':
                {
                  const toolPart: DynamicToolUIPart = {
                    type: 'dynamic-tool',
                    toolCallId: content.toolCallId,
                    toolName: content.toolName,
                    input: content.input,
                    state: 'input-available',
                    ...(content.providerOptions
                      ? { callProviderMetadata: content.providerOptions }
                      : {}),
                  }
                  uiMessage.parts.push(toolPart)
                }
                break
              case 'tool-result': {
                // Attach tool results to existing tool-call part in this assistant message if found
                const toolPart = uiMessage.parts.find(
                  (part) =>
                    (part.type === 'dynamic-tool' || isToolUIPart(part)) &&
                    part.toolCallId === content.toolCallId,
                ) as ToolUIPart<UITools> | DynamicToolUIPart | undefined

                if (toolPart) {
                  toolPart.output = content.output.value
                  const outputStr =
                    typeof content.output === 'string'
                      ? content.output
                      : JSON.stringify(content.output)
                  if (
                    outputStr.includes('Error:') ||
                    outputStr.includes('error:')
                  ) {
                    toolPart.state = 'output-error'
                    if ('errorText' in toolPart) {
                      ;(
                        toolPart as DynamicToolUIPart & { errorText?: string }
                      ).errorText = outputStr
                    }
                  } else {
                    toolPart.state = 'output-available'
                  }
                }
                break
              }
            }
          }
        }

        break
      }

      case 'tool': {
        // Tool messages typically contain results that should be associated with previous assistant messages
        // Find the last assistant message and update its tool parts with results
        if (uiMessage && Array.isArray(modelMessage.content)) {
          for (const content of modelMessage.content) {
            if (content.type === 'tool-result') {
              // Find the corresponding tool part in the assistant message
              const toolPart = uiMessage.parts.find(
                (part) =>
                  (part.type === 'dynamic-tool' || isToolUIPart(part)) &&
                  part.toolCallId === content.toolCallId,
              ) as ToolUIPart<UITools> | DynamicToolUIPart | undefined

              if (toolPart) {
                toolPart.output = content.output.value
                // Check if the output indicates an error
                const outputStr =
                  typeof content.output === 'string'
                    ? content.output
                    : JSON.stringify(content.output)
                if (
                  outputStr.includes('Error:') ||
                  outputStr.includes('error:')
                ) {
                  toolPart.state = 'output-error'
                  if ('errorText' in toolPart) {
                    ;(
                      toolPart as DynamicToolUIPart & { errorText?: string }
                    ).errorText = outputStr
                  }
                } else {
                  toolPart.state = 'output-available'
                }
              }
            }
          }
        }
        break
      }
    }
  }

  return uiMessage
}
```

I made a workaround that allows passing the message received from the provider and getting a UI Message using the AI SDK logic without creating own parser
This solution for OpenAI provider, but i think its not difficult to create different one for another providers using same approach:

```typescript
import { generateId, generateText } from "ai"
import { createOpenAI } from "@ai-sdk/openai"

// Retrieving messages from OpenAI conversation
const items: ConversationItem[] = []

for await (const item of openAIClient.conversations.items.list(thread.conversation, {
  order: "asc",
  limit: 100
})) {
  items.push(item)
}

const uiMessages = await Promise.all<UIMessage>(
  items
    // I added support only for messages, but you can extend this logic for tool calls too
    .filter((item) => item.type === "message")
    .map(async (message) => {
      // Creating UI Message object for user input
      if (message.role === "user") {
        return {
          id: generateId(),
          role: "user",
          parts: message.content
            .map((part) => {
              if (part.type === "input_text") {
                return {
                  type: "text",
                  text: part.text
                }
              }
            })
            .filter(Boolean)
        } as UIMessage
      }

      // Converting OpenAI conversation item using AI SDK provider logic, without creating own implementation 
      const { content } = await generateText({
        prompt: "",
        model: createOpenAI({
          apiKey: "",
          fetch: () =>
            Promise.resolve(
              new Response(
                JSON.stringify({
                  output: [message],
                  created_at: 0,
                  usage: {
                    input_tokens: 0,
                    output_tokens: 0
                  }
                }),
                {
                  status: 200,
                  headers: {
                    "Content-Type": "application/json"
                  }
                }
              )
            )
        })("gpt-5.1")
      })

      return {
        id: generateId(),
        role: "assistant",
        parts: content
      } as UIMessage
    })
)
