While waiting for the official documentation on this breaking change, here's a working code example of how to achieve persistent chat state across components using a singleton pattern to create and reuse the chat instance mentioned by @nicoalbanese:

```
'use client';

import { Chat, UIMessage } from '@ai-sdk/react';

// Singleton chat instance storage
const chatInstances = new Map<string, Chat<UIMessage>>();

// Helper function to get or create chat instance
function getChatInstance(
  id: string,
  initialMessages?: UIMessage[],
  // Add other configuration parameters as needed
): Chat<UIMessage> {
  if (!chatInstances.has(id)) {
    const chat = new Chat<UIMessage>({
      id,
      messages: initialMessages,
    });

    chatInstances.set(id, chat);
  }

  const instance = chatInstances.get(id);
  if (!instance) {
    throw new Error(`Chat instance with id ${id} not found`);
  }
  return instance;
}

// In your React Chat component
function Chat({ chatId, initialMessages }) {
  // Get or create singleton chat instance
  const chat = getChatInstance(chatId, initialMessages);

  // Pass the singleton instance to useChat
  const { messages, sendMessage, status } = useChat({ chat });

  // Your component logic...
}
