```
import type { JSONSchema7, LanguageModelV2Middleware } from '@ai-sdk/provider';

export const sonnetWithReasoningSchemaPatch: LanguageModelV2Middleware = {
	transformParams: ({ params }) => {
		// we grab the schema and turn it to an optional tool call, but direct the llm to use the tool
		// this is because forcing tool choice with thinking doesn't work
		params.toolChoice = { type: 'auto' };
		params.tools = [
			{
				type: 'function',
				description: 'Respond with a JSON object.',
				inputSchema: (params.responseFormat as { schema: JSONSchema7 })?.schema,
				name: 'json',
			},
		];
		params.responseFormat = {
			type: 'text',
		};
		params.prompt.push({
			role: 'user',
			content: [
				{
					type: 'text',
					text: 'Once you have your answer, please use the json tool to provide it. No other text is needed.',
				},
			],
			providerOptions: undefined,
		});
		return Promise.resolve(params);
	},
	wrapGenerate: async ({ doGenerate }) => {
		const result = await doGenerate();

		// if we get more than one text block then schema parsing will fail, so only keep the tool call and reasoning
		const filteredContent = result.content.filter((m) => m.type === 'tool-call' || m.type === 'reasoning');

		// we grab the tool call and transform it to a text response so it get's parsed
		const toolCall = filteredContent.map((m) => {
			if (m.type === 'tool-call') {
				return { type: 'text' as const, text: m.input };
			}
			return m;
		});
		return {
			...result,
			content: toolCall,
		};
	},
};
```

