As per Hamel's [Show Me the Prompt](https://hamel.dev/blog/posts/prompt/) article, I often find it useful to [MITM](https://www.mitmproxy.org/) my code using the AI SDK and an LLM provider.

Using the currently provided interface, its relatively straight forward to do this using [`ProxyAgent`](https://undici.nodejs.org/#/docs/api/ProxyAgent.md) from `undici`:

```ts
import { createAnthropic } from '@ai-sdk/anthropic';
import { createGoogleGenerativeAI } from '@ai-sdk/google';
import { ProxyAgent, type RequestInit as UndiciRequestInit, fetch as undiciFetch } from 'undici';

const HTTP_PROXY = process.env.HTTP_PROXY; // eg. http://localhost:8080/

function proxyFetch(input: RequestInfo | URL, init?: RequestInit) {
  const dispatcher = new ProxyAgent({
    uri: HTTP_PROXY,
    requestTls: {
      rejectUnauthorized: false,
    },
    proxyTls: {
      rejectUnauthorized: false,
    },
  });

  let url: string | URL;
  if (typeof input === 'string') {
    url = input;
  } else if (input instanceof URL) {
    url = input;
  } else if (input instanceof Request) {
    url = input.url;
  } else {
    throw new Error(`Unsupported input type: ${typeof input}`);
  }

  if (!init) {
    return undiciFetch(url, {
      dispatcher,
    }) as Promise<Response>;
  }

  (init as UndiciRequestInit).dispatcher = dispatcher;
  return undiciFetch(url, init as UndiciRequestInit) as Promise<Response>;
}

export const google = createGoogleGenerativeAI(HTTP_PROXY ? { fetch: proxyFetch } : {});
export const anthropic = createAnthropic(HTTP_PROXY ? { fetch: proxyFetch } : {});
```

It might be nice if a) this behaviour was "built-in" and accessible via a common env var like `AI_HTTP_PROXY` and/or b) configurable in a single place such that I didn't need to set it up for every provider I use.

