```typescript
let providerOptions = undefined;
const firstAssistantMsg = message.find((msg) => msg.role === "assistant");
if(firstAssistantMsg && Array.isArray(firstAssistantMsg.content)){
const reasoningBlock = firstAssistantMsg.content.find((cont) => cont.type === "reasoning");
if(reasoningBlock && reasoningBlock.providerOptions){
providerOptions = reasoningBlock.providerOptions
}
