```ts
const useDynamicChatTransport = <UI_MESSAGE extends UIMessage = UIMessage>(
  transport: ChatTransport<UI_MESSAGE>,
): ChatTransport<UI_MESSAGE> => {
  const transportRef = useRef<ChatTransport<UI_MESSAGE>>(transport);
  useEffect(() => {
    transportRef.current = transport;
  });
  const dynamicTransport = useMemo(
    () =>
      new Proxy(transportRef.current, {
        get(_, prop) {
          const res =
            transportRef.current[prop as keyof ChatTransport<UI_MESSAGE>];
          return typeof res === "function"
            ? res.bind(transportRef.current)
            : res;
        },
      }),
    [],
  );
  return dynamicTransport;
};

useChat({
  transport: useDynamicChatTransport(new HttpChatTransport({
    body: { myValue },
  })),
});
```

Another workaround that seems to work is using a **dynamic `body` function** combined with `useEffectEvent`.

```ts
const getBody = useEffectEvent(() => ({ subagent }))

useChat({
  transport: new DefaultChatTransport({
    // eslint-disable-next-line react-hooks/rules-of-hooks
    body: () => getBody(),
  }),
})

```

>[!WARNING]
>  This relies on current React behavior and uses `useEffectEvent` outside its intended scope, so it’s a pragmatic but not future‑proof workaround.

