I created this middleware to dynamically add correct settings when tool is called with Nova in case anyone else would like:

```ts
import type { LanguageModelV2Middleware } from "@ai-sdk/provider";

/**
 * Amazon Nova's [Troubleshooting Tool Calls Docs](https://docs.aws.amazon.com/nova/latest/userguide/prompting-tool-troubleshooting.html)
 * recommend setting temperature to 0 when using tools. This
 * automatically sets that up. Prevents the error: `Model produced invalid
 * sequence as part of ToolUse`
 */
export const novaToolSettingsMiddleware: LanguageModelV2Middleware = {
  transformParams: async ({ params }) => {
    /**
     * The AI SDK automatically adds a JSON response tool if `generateObject`
     * is used with a `schema`. See [here](https://github.com/vercel/ai/blob/558551018d9a9c2fd6faff14c07366e883124660/packages/amazon-bedrock/src/bedrock-chat-language-model.ts#L137)
     * We still want to follow Nova's recommendation for tool calling in this case.
     */
    const isAiSdkJsonTool =
      params.responseFormat?.type === "json" && params.responseFormat !== null;
    if (params.tools?.length || isAiSdkJsonTool) {
      params.temperature = 0;
      // topK = 1 is recommended by Nova docs: https://docs.aws.amazon.com/nova/latest/userguide/prompting-tool-troubleshooting.html
      params.topK = 1;
    }
    return params;
  },
};
```

