```
import { stepCountIs, streamText, tool } from "ai";
import { openai } from "@ai-sdk/openai";
import { z } from "zod/v4";
import { ModelMessage } from "@ai-sdk/provider-utils";

const rollDiceTool = tool({
  description: "Roll a dice and get a random number from 1 to 6",
  inputSchema: z.object({}),
  execute: async () => {
    const result = Math.floor(Math.random() * 6) + 1;
    return { result };
  },
});

async function prompt(message: string): Promise<string> {
  const encoder = new TextEncoder();
  const decoder = new TextDecoder();

  await Deno.stdout.write(encoder.encode(message));

  const buf = new Uint8Array(1024);
  const n = await Deno.stdin.read(buf);

  if (n === null) return "";

  return decoder.decode(buf.subarray(0, n)).trim();
}

async function chat() {
  console.log('AI Chat CLI - Type "exit" to quit\n');
  const messages: ModelMessage[] = [];

  while (true) {

    const userInput = await prompt("You: ");

    messages.push({
      role: 'user',
      content: userInput,
    });

    console.log();

    if (userInput.toLowerCase() === "exit") {
      console.log("\nGoodbye!");
      break;
    }

    try {
      const result = await streamText({
        model: openai('gpt-5'),
        tools: {
          roll_dice: rollDiceTool
        },
        stopWhen: stepCountIs(1000),
        prompt: messages,
      });

      for await (const chunk of result.fullStream) {
        if (chunk.type === 'text-delta') {
          Deno.stdout.write(new TextEncoder().encode(chunk.text));
        }
        if (chunk.type === 'text-start') {
          Deno.stdout.write(new TextEncoder().encode('AI: '));
        }
        if (chunk.type === 'text-end') {
          console.log('\n');
        }

        if (chunk.type === 'tool-call') {
          console.log('Tool call:', chunk.toolName);
          console.log(JSON.stringify(chunk.input, null, 2));
          console.log();
        }
        if (chunk.type === 'tool-result') {
          console.log('Tool result:', chunk.toolName);
          console.log(JSON.stringify(chunk.output, null, 2));
          console.log();
        }
      }

      const steps = await result.steps;
      for (const step of steps) {
        messages.push(...step.response.messages)
      }
    } catch (error) {
      console.error("\nError:", error);
      console.log();
    }
  }
}

chat();
```

