Ended up using a modified version of how Mastra does this that will work for us during the migration if anyone else runs into this. Just use `pipeV5StreamToV4Response` instead of `pipeUIMessageStreamToResponse` when the client is still on v4.

```ts
/** Pipes an AI SDK v5 UIMessage stream to a router response in a v4 compatible format. */
export function pipeV5StreamToV4Response(response: Response, stream: ReadableStream<UIMessageChunk>): void {
  const v4Response = createV4Response(stream);
  void pipeV4ResponseToResponse(v4Response, response);
}

async function pipeV4ResponseToResponse(v4Response: Response, routerResponse: Response) {
  v4Response.headers.forEach((value, key) => {
    routerResponse.setHeader(key, value);
  });
  routerResponse.status(v4Response.status);
  if (!v4Response.body) {
    routerResponse.end();
    return;
  }
  const reader = v4Response.body.getReader();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        break;
      }

      routerResponse.write(value);
    }
    routerResponse.end();
  } catch (error) {
    routerResponse.status(500).end();
  }
}

function createV4Response(v5Stream: ReadableStream<UIMessageChunk>) {
  const v4Stream = v5Stream.pipeThrough(createV5ToV4Transformer()).pipeThrough(new TextEncoderStream());
  return new Response(v4Stream, {
    status: 200,
    headers: {
      "Cache-Control": "no-cache",
    },
  });
}

type StreamState = {
  messageCounter: number;
  stepCounter: number;
};

function createV5ToV4Transformer() {
  const state: StreamState = {
    messageCounter: 0,
    stepCounter: 0,
  };
  return new TransformStream<UIMessageChunk, string>({
    transform(chunk, controller) {
      try {
        const v4Chunk = transformV5ChunkToV4(chunk, state);
        if (v4Chunk) {
          controller.enqueue(v4Chunk + "\n");
        }
      } catch (transformError) {
        // noop
      }
    },
  });
}

/** Map of v5 stream prefixes to v4 stream prefixes. */
const DataStreamStringPrefixes = {
  text: "0",
  data: "2",
  error: "3",
  message_annotations: "8",
  tool_call: "9",
  tool_result: "a",
  tool_call_streaming_start: "b",
  tool_call_delta: "c",
  finish_message: "d",
  finish_step: "e",
  start_step: "f",
  reasoning: "g",
  source: "h",
  redacted_reasoning: "i",
  reasoning_signature: "j",
  file: "k",
};

function transformV5ChunkToV4(chunk: UIMessageChunk, state: StreamState) {
  switch (chunk.type) {
    case "text-start":
      return null;
    case "text-delta":
      return `${DataStreamStringPrefixes.text}:${JSON.stringify(chunk.delta)}`;
    case "text-end":
      return null;
    case "error":
      try {
        const errorData =
          typeof chunk.errorText === "string"
            ? {
                message: chunk.errorText,
                code: "STREAM_ERROR",
                timestamp: Date.now(),
              }
            : chunk.errorText;
        return `${DataStreamStringPrefixes.error}:${JSON.stringify(errorData)}`;
      } catch {
        return `${DataStreamStringPrefixes.error}:${JSON.stringify({
          message: "Stream error",
          code: "TRANSFORM_ERROR",
        })}`;
      }
    case "tool-input-start":
    case "tool-input-delta":
      // Don't stream partial tool calls for v4
      return null;
    case "tool-input-available":
      return `${DataStreamStringPrefixes.tool_call}:${JSON.stringify({
        toolCallId: chunk.toolCallId,
        toolName: chunk.toolName,
        args: chunk.input,
      })}`;
    case "tool-output-available":
      return `${DataStreamStringPrefixes.tool_result}:${JSON.stringify({
        toolCallId: chunk.toolCallId,
        result: chunk.output,
      })}`;
    case "reasoning-start":
      return null;
    case "reasoning-delta":
      return `${DataStreamStringPrefixes.reasoning}:${JSON.stringify(chunk.delta)}`;
    case "reasoning-end":
      return null;
    case "start":
      return null;
    case "finish":
      return `${DataStreamStringPrefixes.finish_message}:${JSON.stringify({
        finishReason: "stop",
        metadata: chunk.messageMetadata,
      })}`;
    case "start-step":
      state.stepCounter++;
      const stepId = generateId(`step-${state.stepCounter}`);
      return `${DataStreamStringPrefixes.start_step}:${JSON.stringify({
        messageId: stepId,
      })}`;
    case "finish-step":
      return `${DataStreamStringPrefixes.finish_step}:${JSON.stringify({
        finishReason: "stop",
        usage: {
          promptTokens: 0,
          completionTokens: 0,
        },
        isContinued: false,
      })}`;
    case "message-metadata":
      return `${DataStreamStringPrefixes.message_annotations}:${JSON.stringify([
        {
          messageId: generateId("msg"),
          metadata: chunk.messageMetadata,
        },
      ])}`;
    case "file":
      if ("url" in chunk && "mediaType" in chunk) {
        return `${DataStreamStringPrefixes.file}:${JSON.stringify({
          url: chunk.url,
          mediaType: chunk.mediaType,
        })}`;
      }
      return null;
    case "source-url":
      return `${DataStreamStringPrefixes.source}:${JSON.stringify({
        id: chunk.sourceId,
        title: chunk.title,
        url: chunk.url,
      })}`;
    case "source-document":
      return `${DataStreamStringPrefixes.source}:${JSON.stringify({
        id: chunk.sourceId,
        title: chunk.title,
        mediaType: chunk.mediaType,
        filename: chunk.filename,
      })}`;
    default:
      // Unknown chunk type, ignore
      return null;
  }
}

function generateId(prefix: string) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

