@julien-blanchon the cleanup function I use is in the snippet below. The role of the message is `user` but could also be `assistant` for image generation use cases for example.

```
tsx tool_image_generation.ts --cleanup
```

```typescript
import { openai } from "@ai-sdk/openai";
import type { ModelMessage, UserModelMessage } from "ai";
import { stepCountIs, streamText } from "ai";
import * as readline from "node:readline/promises";
import { z } from "zod";

import "dotenv/config";

const terminal = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
});

const messages: ModelMessage[] = [];

function sanitizeMessages(modelMessages: ModelMessage[]) {
    const sanitizedMessages: ModelMessage[] = [];
    for (const mess of modelMessages) {
        sanitizedMessages.push(mess);
        if (mess.role === "tool") {
            const content = mess.content[0];
            if (
                content &&
                content.output &&
                content.output.type === "content" &&
                content.output.value.length > 0
            ) {
                // @ts-ignore
                if (content.output.value[0].data) {
                    const newMess: UserModelMessage = {
                        role: "user",
                        content: [
                            {
                                type: "image",
                                // @ts-ignore
                                image: content.output.value[0].data as string,
                            },
                        ],
                    };
                    content.output = {
                        type: "text",
                        value: "[Image sent]",
                    };
                    sanitizedMessages.push(newMess);
                } else {
                    console.warn(
                        "Tool returned content with no data",
                        JSON.stringify(content)
                    );
                }
            }
        }
    }
    return sanitizedMessages;
}

async function main() {
    while (true) {
        const userInput = await terminal.question("You: ");

        messages.push({ role: "user", content: userInput });
        const useCleanup = process.argv.includes("--cleanup");
        const sanitizedMessages = useCleanup
            ? sanitizeMessages(messages)
            : messages;
        const result = streamText({
            model: openai("gpt-4o"),
            messages: sanitizedMessages,
            tools: {
                // server-side tool with execute function:
                generateImage: {
                    description:
                        "generate an image from a text prompt, use it with a random prompt if the user just ask for image generation",
                    inputSchema: z.object({ prompt: z.string() }),
                    execute: async ({}: { prompt: string }) => {
                        // Fetch an image from the web and return it as base64
                        const imageUrl =
                            "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=400&q=80";
                        const response = await fetch(imageUrl);
                        if (!response.ok) {
                            throw new Error(
                                `Failed to fetch image: ${response.statusText}`
                            );
                        }
                        const buffer = Buffer.from(
                            await response.arrayBuffer()
                        );
                        const base64 = buffer.toString("base64");
                        return {
                            imageBase64: base64,
                            mimeType: "image/jpeg",
                            sourceUrl: imageUrl,
                        };
                    },
                    toModelOutput: (image) => {
                        return {
                            type: "content",
                            value: [
                                {
                                    type: "media",
                                    mediaType: image.mimeType,
                                    data: `data:${image.mimeType};base64,${image.imageBase64}`,
                                },
                            ],
                        };
                    },
                },
            },
            onStepFinish: (step) => {
                console.log("Step finished:", step.toolCalls, step.usage);
            },
            stopWhen: stepCountIs(1),
        });

        let fullResponse = "";
        process.stdout.write("\nAssistant: ");
        for await (const delta of result.textStream) {
            fullResponse += delta;
            process.stdout.write(delta);
        }
        process.stdout.write("\n\n");

        messages.push(...(await result.response).messages);
    }
}

