On the server side, a subagent acts as a tool for the main agent:

```ts
enum DATA_SUB_AGENT_TYPE {
  SUB_AGENT_SESSION_START = 'data-subagent-start',
  SUB_AGENT_SESSION_STREAMING = 'data-subagent-streaming',
  SUB_AGENT_SESSION_FINISH = 'data-subagent-finish',
}

function sendSubAgentMessageChunk(
  context: AgentRuntimeContext,
  toolCallId: ToolUIPart['toolCallId'],
  lifecycle: DATA_SUB_AGENT_TYPE,
  chunk?: UIMessageChunk,
) {
  context.dataStream.write({
    type: lifecycle,
    id: `subagent-${toolCallId}`,
    data: { id: toolCallId, chunk },
    transient: true,
  } as SubAgentDataChunk);
}

tool({
    title,
    description,
    inputSchema,
    async execute(
      input,
      { toolCallId, abortSignal },
    ): Promise<UIMessage> {
      const agent = new ToolLoopAgent({
        model,
        instructions,
        tools,
        stopWhen: [stepCountIs(20)],
      });

      const result = await agent.stream({
        prompt,
        abortSignal,
      });

      return new Promise(async (resolve) => {
        const stream = result.toUIMessageStream({
          onFinish({ messages }) {
            resolve(messages[0]);
          },
          onError() {
            resolve({
              id: generateId(),
              role: 'assistant',
              parts: [{ type: 'text', text: 'An error occurred.' }],
            });

            return 'An error occurred.';
          },
        });

        sendSubAgentMessageChunk(
          context,
          toolCallId,
          DATA_SUB_AGENT_TYPE.SUB_AGENT_SESSION_START,
        );

        for await (const chunk of stream) {
          sendSubAgentMessageChunk(
            context,
            toolCallId,
            DATA_SUB_AGENT_TYPE.SUB_AGENT_SESSION_STREAMING,
            chunk,
          );
        }

        sendSubAgentMessageChunk(
          context,
          toolCallId,
          DATA_SUB_AGENT_TYPE.SUB_AGENT_SESSION_FINISH,
        );
      });
    },
});
```

The client merges the data stream into the subagent tool output:

```ts
import { readUIMessageStream, type UIMessage, type UIMessageChunk } from 'ai';
import { useRef, useState, useCallback, useEffect } from 'react';

enum DATA_SUB_AGENT_TYPE {
  SUB_AGENT_SESSION_START = 'data-subagent-start',
  SUB_AGENT_SESSION_STREAMING = 'data-subagent-streaming',
  SUB_AGENT_SESSION_FINISH = 'data-subagent-finish',
}

export function useAgentSubMessages() {
  const [messages, setMessages] = useState<Map<string, UIMessage>>(new Map());
  const controllers = useRef<Map<string, ReadableStreamDefaultController<UIMessageChunk>>>(
    new Map(),
  );
  const abortControllers = useRef<Map<string, AbortController>>(new Map());

  const cleanup = useCallback(() => {
    abortControllers.current.forEach((ac) => ac.abort());
    controllers.current.forEach((controller) => {
      try {
        controller.close();
      } catch {
      }
    });
    controllers.current.clear();
    abortControllers.current.clear();
    setMessages(new Map());
  }, []);

  useEffect(() => {
    return cleanup;
  }, [cleanup]);

  const handleChunk = useCallback((data: SubAgentDataChunk) => {
    if (data.type === DATA_SUB_AGENT_TYPE.SUB_AGENT_SESSION_START) {
      const { id: agentId } = data.data;

      if (controllers.current.has(agentId)) {
        const oldController = controllers.current.get(agentId);
        try {
          oldController?.close();
        } catch {
        }
        controllers.current.delete(agentId);
      }
      if (abortControllers.current.has(agentId)) {
        abortControllers.current.get(agentId)?.abort();
        abortControllers.current.delete(agentId);
      }

      const abortController = new AbortController();
      abortControllers.current.set(agentId, abortController);

      let controller: ReadableStreamDefaultController<UIMessageChunk>;
      const stream = new ReadableStream<UIMessageChunk>({
        start(c) {
          controller = c;
          controllers.current.set(agentId, controller);
        },
      });
      const messageStream = readUIMessageStream({ stream });

      (async () => {
        try {
          for await (const message of messageStream) {
            if (abortController.signal.aborted) {
              break;
            }
            setMessages((prev) => {
              const next = new Map(prev);
              next.set(agentId, message);
              return next;
            });
          }
        } catch (error) {
          if (!abortController.signal.aborted) {
            console.error(`SubAgent ${agentId} stream error:`, error);
          }
        } finally {
          controllers.current.delete(agentId);
          abortControllers.current.delete(agentId);
        }
      })();
    } else if (data.type === DATA_SUB_AGENT_TYPE.SUB_AGENT_SESSION_STREAMING) {
      const { id: agentId, chunk } = data.data;
      const controller = controllers.current.get(agentId);
      if (controller) {
        try {
          controller.enqueue(chunk);
        } catch (error) {
          console.warn(`Failed to enqueue chunk for ${agentId}:`, error);
        }
      } else {
        console.warn(`No controller found for agent ${agentId}, chunk dropped`);
      }
    } else if (data.type === DATA_SUB_AGENT_TYPE.SUB_AGENT_SESSION_FINISH) {
      const { id: agentId } = data.data;
      const controller = controllers.current.get(agentId);
      if (controller) {
        try {
          controller.close();
        } catch {
        }
        controllers.current.delete(agentId);
      }
    }
  }, []);

  return { messages, handleChunk, cleanup };
}

function isSubAgentToolPart(part: UIMessagePart<UIDataTypes, UITools>): boolean {
  return isToolUIPart(part) && part.type.startsWith('tool-agent');
}

function mergeSubAgentOutputToMessages(
  messages: UIMessage[],
  subAgentMessages: Map<string, UIMessage>,
): UIMessage[] {
  if (messages.length === 0) return messages;

  const lastMessage = messages[messages.length - 1];
  if (lastMessage.role !== 'assistant' || !lastMessage.parts?.length) return messages;

  const lastPart = lastMessage.parts[lastMessage.parts.length - 1];
  if (!isToolUIPart(lastPart) || !isSubAgentToolPart(lastPart)) return messages;

  const toolPart = lastPart as ToolUIPart;
  if (toolPart.output) return messages;

  const subAgentMessage = subAgentMessages.get(toolPart.toolCallId);
  if (!subAgentMessage) return messages;

  return messages.map((msg, idx) => {
    if (idx !== messages.length - 1) return msg;
    return {
      ...msg,
      parts: msg.parts.map((part, partIdx) => {
        if (partIdx !== msg.parts.length - 1) return part;
        return { ...part, output: subAgentMessage } as typeof part;
      }),
    };
  });
}

export function useAgent({ appId, initialMessages = [], onData, onFinish }: UseAgentOptions) {
  const { messages: subAgentMessages, handleChunk, cleanup } = useAgentSubMessages();

  const { messages, sendMessage, status } = useChat({
    id: appId,
    transport: new DefaultChatTransport({
      api: '/api/chat',
      prepareSendMessagesRequest: ({ id, messages }) => {
        return {
          body: {
            id,
            message: messages[messages.length - 1],
          },
        };
      },
    }),
    messages: initialMessages.length > 0 ? initialMessages : undefined,
    resume: true,
    onData: (...args) => {
      if (
        args[0].type === 'data-subagent-start' ||
        args[0].type === 'data-subagent-streaming' ||
        args[0].type === 'data-subagent-finish'
      ) {
        handleChunk(args[0] as Parameters<typeof handleChunk>[0]);
      }
    },
  });

  const mergedMessages = useMemo(
    () => mergeSubAgentOutputToMessages(messages, subAgentMessages),
    [messages, subAgentMessages],
  );

  return {
    messages: mergedMessages,
    sendMessage,
    status,
  };
}
```

