diff --git a/dist/index.mjs b/dist/index.mjs
index 2c67f05d4582cee04ce1e9317895e75c2c9df6ac..91d8b6f753386245a9fe2e375669819cd82988d6 100644
--- a/dist/index.mjs
+++ b/dist/index.mjs
@@ -11015,8 +11015,9 @@ var AbstractChat = class {
     let isAbort = false;
     let isDisconnect = false;
     let isError = false;
+    let activeResponse;
     try {
-      const activeResponse = {
+      activeResponse = {
         state: createStreamingUIMessageState({
           lastMessage: this.state.snapshot(lastMessage),
           messageId: this.generateId()
@@ -11106,14 +11107,20 @@ var AbstractChat = class {
       this.setStatus({ status: "error", error: err });
     } finally {
       try {
-        (_b = this.onFinish) == null ? void 0 : _b.call(this, {
-          message: this.activeResponse.state.message,
-          messages: this.state.messages,
-          isAbort,
-          isDisconnect,
-          isError,
-          finishReason: (_a15 = this.activeResponse) == null ? void 0 : _a15.state.finishReason
-        });
+        // PATCH: Use local `activeResponse` instead of `this.activeResponse` in finally block.
+        // `this.activeResponse` can be undefined if an error is thrown before assignment,
+        // or overwritten by concurrent `makeRequest` calls. Local var is safe.
+        // See: https://github.com/vercel/ai/issues/8477
+        if (activeResponse) {
+          (_b = this.onFinish) == null ? void 0 : _b.call(this, {
+            message: activeResponse.state.message,
+            messages: this.state.messages,
+            isAbort,
+            isDisconnect,
+            isError,
+            finishReason: (_a15 = activeResponse) == null ? void 0 : _a15.state.finishReason
+          });
+        }
       } catch (err) {
         console.error(err);
       }
```

