or should i create 

```bash
/**
 * Creates a sanitized ToolResultPart, ensuring that any `undefined`
 * values inside JSON outputs are converted to `null`.
 */
export function createToolResultPart(
  params: Omit<ToolResultPart, 'type' | 'output'> & {
    output: ToolResultPart['output'];
  }
): ToolResultPart {
  const sanitizedOutput =
    params.output.type === 'json' || params.output.type === 'error-json'
      ? { ...params.output, value: sanitizeJSONValue(params.output.value) }
      : params.output;

  return {
    ...params,
    type: 'tool-result',
    output: sanitizedOutput,
  };
}

/**
 * Recursively replaces all `undefined` values with `null`
 * in a JSON-like structure to make it a valid JSONValue.
 */
export function sanitizeJSONValue<T>(value: T): T {
  if (value === undefined) {
    return null as T;
  }

  if (Array.isArray(value)) {
    return value.map(v => sanitizeJSONValue(v)) as T;
  }

  if (value !== null && typeof value === 'object') {
    const obj: Record<string, any> = {};
    for (const [key, val] of Object.entries(value)) {
      obj[key] = sanitizeJSONValue(val);
    }
    return obj as T;
  }

  return value;
}
```

