The function looks something like this:

```typescript

export function createToolCallRepairFunction<TOOLS extends ToolSet>(
  tools: TOOLS,
): (options: {
  toolCall: LanguageModelV2ToolCall;
  error: NoSuchToolError | InvalidToolInputError;
}) => Promise<LanguageModelV2ToolCall | null> {
  return async ({ toolCall, error }) => {
    if (error instanceof InvalidToolInputError) {
      ...
    }

    const availableToolNames = Object.keys(tools);
    const cleanedToolName = toolCall.toolName
      .replace(/[^a-zA-Z0-9_-]/g, "")
      .trim();

    const exactMatch = availableToolNames.find(
      (name) => name.toLowerCase() === cleanedToolName.toLowerCase(),
    );

    if (exactMatch) {
      return {
        ...toolCall,
        toolName: exactMatch,
      };
    }

    const partialMatch = availableToolNames.find((name) =>
      name.toLowerCase().includes(cleanedToolName.toLowerCase()),
    );

    if (partialMatch) {
      return {
        ...toolCall,
        toolName: partialMatch,
      };
    }

    const reverseMatch = availableToolNames.find((name) =>
      cleanedToolName.toLowerCase().includes(name.toLowerCase()),
    );

    if (reverseMatch) {
      Sentry.captureMessage("Tool call repaired with reverse match", {
        level: "info",
        extra: {
          originalToolName: toolCall.toolName,
          repairedToolName: reverseMatch,
          cleanedToolName,
        },
      });

      return {
        ...toolCall,
        toolName: reverseMatch,
      };
    }

    return null;
  };
}

```

