    const parsedBody = options?.body ? JSON.parse(options.body.toString()) : null;
    const newOptions = {
      ...options,
      body: parsedBody ? JSON.stringify({...parsedBody, truncation: 'auto'}, null, 2) : options?.body,
    }
    return await fetch(url, newOptions);
  },
});

