I'm not sure, I fully understand what you're trying to achieve but we do the following: 
1. define the zod schema
2. transform zod schema to JSON schema -> keeps the descriptions + examples of the zod schema -> somewhat softens/weakens the types
3. extract with JSON schema
4. validate the extraction result using zod's `.transform` + validate/post-process to achieve stricter types again

```typescript
import { jsonSchema, type JSONSchema7 } from 'ai'
import { z } from 'zod/v4'

/**
 * Converts a Zod schema to JSON Schema while preserving descriptive metadata and proper handling of unsupported types.
 */
export const zodToJsonSchema = <T extends z.ZodTypeAny>(zodSchema: T): JSONSchema7 => {
  return z.toJSONSchema(zodSchema, {
    io: 'input',
    target: 'draft-7',
    unrepresentable: 'any',
  }) as JSONSchema7
}

/**
 * Wraps a Zod schema so `generateObject` gets rich JSON Schema metadata yet still validates with Zod.
 */
export const jsonSchemaWithZodValidation = <T extends z.ZodTypeAny>(zodSchema: T) => {
  return jsonSchema(() => zodToJsonSchema(zodSchema), {
    validate: async (value) => {
      const result = await zodSchema.safeParseAsync(value)
      return result.success
        ? { success: true, value: result.data }
        : { success: false, error: result.error }
    },
  })
}

```

