```ts
import type { ModelMessage } from 'ai'

export default function pruneOpenAiMessages({
    messages,
    keepLastReasoningCount = 0,
    toolCalls = [],
    emptyMessages = 'remove',
}: {
    messages: ModelMessage[]
    keepLastReasoningCount?: number
    toolCalls?: Array<{
        keepLastMessagesCount: number
        tools?: string[]
    }>
    emptyMessages?: 'keep' | 'remove'
}): ModelMessage[] {
    // filter reasoning parts:
    if (keepLastReasoningCount) {
        messages = messages.filter((message, messageIndex) => {
            if (
                message.role !== 'assistant' ||
                typeof message.content === 'string' ||
                messageIndex >= messages.length - keepLastReasoningCount
            ) {
                return true
            }

            if (message.content.find((part) => part.type === 'reasoning')) {
                return false
            }

            return true
        })
    }

    for (const toolCall of toolCalls) {
        // determine how many trailing messages to keep:
        const keepLastMessagesCount = toolCall.keepLastMessagesCount

        // scan kept messages to identify tool calls and approvals that need to be kept:
        const keptToolCallIds: Set<string> = new Set()

        if (keepLastMessagesCount != null) {
            for (const message of messages.slice(-keepLastMessagesCount)) {
                if (
                    (message.role === 'assistant' || message.role === 'tool') &&
                    typeof message.content !== 'string'
                ) {
                    for (const part of message.content) {
                        if (
                            part.type === 'tool-call' ||
                            part.type === 'tool-result'
                        ) {
                            keptToolCallIds.add(part.toolCallId)
                        }
                    }
                }
            }
        }

        messages = messages.filter((message, messageIndex) => {
            if (
                (message.role !== 'assistant' && message.role !== 'tool') ||
                typeof message.content === 'string' ||
                (keepLastMessagesCount &&
                    messageIndex >= messages.length - keepLastMessagesCount)
            ) {
                return message
            }

            const shouldRemove = message.content.find((part) => {
                // keep non-tool parts:
                if (part.type !== 'tool-call' && part.type !== 'tool-result') {
                    return false
                }

                // keep parts that are associated with a tool call that needs to be kept:
                if (keptToolCallIds.has(part.toolCallId)) {
                    return false
                }

                // If no specific tools specified, remove ALL tool calls before threshold
                if (!toolCall.tools) {
                    return true
                }

                // Get tool name (tool-call has it directly, tool-result needs lookup or has toolName)
                const toolName =
                    part.type === 'tool-call'
                        ? part.toolName
                        : (part as { toolName?: string }).toolName

                // Remove if this tool is in the removal list
                if (toolName && toolCall.tools.includes(toolName)) {
                    return true
                }

                return false
            })

            return !shouldRemove
        })
    }

    if (emptyMessages === 'remove') {
        messages = messages.filter((message) => message.content.length > 0)
    }

    return messages
}
```

Found the issue. All MCP tools calls are being saved as JSON, it's just that the text ones the model can still parse, while the image ones, naturally, it cannot. Here is further evidence that a text response is being saved as JSON.

<img width="618" height="486" alt="Image" src="https://github.com/user-attachments/assets/d6fa49ae-e576-4dd2-bedd-2d4922479689" />

The problem stems from [here](https://github.com/vercel/ai/blob/0bc25e99298b77d886fb5e910ab3dd2b36f98c13/packages/ai/src/prompt/create-tool-model-output.ts#L20), where the tools results are stored as JSON if they are not of type string. The MCP client, when calling `tools()`, does not wrap each tools response from the MCP in a converter, so the tools return something of the following form
```json
{
  "content": [
    {
      "type": "text",
      "text": "status: success\ndata:\n  documentId: local-editor/529"
    }
  ],
  "isError": false,
  "structuredContent": {
    "status": "success",
    "data": { "documentId": "local-editor/529" }
  }
}
```
This then gets interpreted as a JSON response by the tool. Then the content returned has images, these do not get treated in a special manner.

The solution is to wrap the result of `self.callTool` within `execute` [here](https://github.com/vercel/ai/blob/0bc25e99298b77d886fb5e910ab3dd2b36f98c13/packages/mcp/src/tool/mcp-client.ts#L519) in the MCP client package so that the correct conversion of the results to the AI SDK's message types is performed.

For anyone that stumbled upon the same issue, the following code solves the MCP tool result parsing. I'll make a pull request to incorporate this (or a fuller version) into the `execute` function.

```ts
import type { experimental_createMCPClient as createMCPClient } from "@ai-sdk/mcp";
import type { SamplingMessageSchema } from "@modelcontextprotocol/sdk/types.js";
import type { Tool } from "ai";
import type { z } from "zod";

type MCPTools = Awaited<
  ReturnType<Awaited<ReturnType<typeof createMCPClient>>["tools"]>
>;

type MCPToolResultContentMessage = z.infer<
  typeof SamplingMessageSchema
>["content"];

type MCPToolResult = {
  content: MCPToolResultContentMessage[];
  isError?: boolean;
  structuredContent: Record<string, unknown>;
};

export const fixMCPTools = (tools: MCPTools): Record<string, Tool> =>
  Object.fromEntries(
    Object.entries(tools).map(
      ([toolName, toolObj]: [string, Tool]): [string, Tool] => [
        toolName,
        {
          ...toolObj,
          toModelOutput: (result: MCPToolResult) => {
            if (typeof result === "string") {
              return { type: "text", text: result };
            }

            if (result.structuredContent !== undefined) {
              return { type: "json", value: result.structuredContent }; // I'd have to look deeper into the docs. Not sure if presence of structured content implies no other messages other than the unstructured equivalent.
            }

            if (result.content === undefined) {
              return { type: "json", value: result };
            }

            return {
              type: "content",
              value: result.content.flatMap((part) => {
                switch (part.type) {
                  case "text":
                    return [
                      {
                        type: "text",
                        text: part.text,
                      },
                    ];

                  case "image":
                    return [
                      {
                        type: "image-data",
                        data: part.data,
                        mediaType: part.mimeType,
                      },
                    ];

                  case "audio":
                    return [
                      {
                        type: "file-data",
                        data: part.data,
                        mediaType: part.mimeType,
                      },
                    ];

                  case "tool_result":
                    return part.content.map((contentBlock) => {
                      switch (contentBlock.type) {
                        case "text":
                          return {
                            type: "text",
                            text: contentBlock.text,
                          };

                        case "image":
                          return {
                            type: "image-data",
                            data: contentBlock.data,
                            mediaType: contentBlock.mimeType,
                          };

                        case "audio":
                          return {
                            type: "file-data",
                            data: contentBlock.data,
                            mediaType: contentBlock.mimeType,
                          };

                        // case "resource_link":
                        // case "resource":
                        default:
                          return {
                            type: "json",
                            value: contentBlock,
                          };
                      }
                    });

                  // case "tool_use":
                  default:
                    return {
                      type: "json",
                      value: part,
                    };
                }
              }),
            };
          },
        },
      ],
    ),
  );
```

Yep, here's the file and the output below. To clarify, in the unfixed case the model understand the image because it's fairly short base64, but the message is being stored as JSON instead of proper image data. In practical terms, for big images, the image is sent as base64 text to the provider on the next round when the `ToolLoopAgent` reads from the previous messages, and the context explodes because big images in base64 are 200k worth of tokens when treated as text.

With your guidance I can work the fix into a PR before the MCP leaves experimental state given that connecting to a multimodal server that returns a sufficiently large blob will kill any AI SDK agent instance by making its context explode and the model provider refusing to process the follow on request.

