          execute: async args => {
            const val = args.optional;
            const typeInfo =
              val === undefined
                ? 'undefined'
                : `${typeof val} (${JSON.stringify(val)})`;

            console.log(`${label.padEnd(60)} | Result: ${typeInfo}`);
            return { success: true };
          },
          ...strictConfig,
        }),
      },
      toolChoice: { type: 'tool', toolName: 'get_weather' },
      prompt: 'Whats the weather in SF?',
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);

    console.log(
      `${label.padEnd(60)} | Error: ${message.substring(0, 50)}...`,
    );
  }
}
